results := make(chan Result)
var wg sync.WaitGroup
for _, job := range jobs {
    wg.Go(func() { results <- process(job) })
}
go func() {
    wg.Wait()
    close(results)       // закрываем, когда все отправители закончили
}()
for r := range results {
    handle(r)
}

for a != nil || b != nil {
    select {
    case v, ok := <-a:
        if !ok { a = nil; continue }   // ветка отключена
        out <- v
    case v, ok := <-b:
        if !ok { b = nil; continue }
        out <- v
    }
}
